package com.osu.michja56.backend.service;

import com.osu.michja56.backend.model.Product;
import com.osu.michja56.backend.repository.ProductRepository;
import org.springframework.stereotype.Service;

import java.util.List;
import java.util.Optional;

@Service
public class    ProductService {

    private final ProductRepository productRepository;

    public ProductService(ProductRepository productRepository) {
        this.productRepository = productRepository;
    }

    public List<Product> getAllProducts() {
        return productRepository.findAll();
    }

    public Optional<Product> getProductById(Long id) {
        return productRepository.findById(id);
    }

    public Product createProduct(Product product) {
        return productRepository.save(product);
    }

    public Optional<Product> updateStock(Long id, int stockQuantity) {
        return productRepository.findById(id).map(product -> {
            product.setStockQuantity(stockQuantity);
            return productRepository.save(product);
        });
    }
    public void deleteProduct(Long id) {
        productRepository.deleteById(id);
    }
}

package com.osu.michja56.backend.service;

import com.osu.michja56.backend.dto.OrderCreateRequest;
import com.osu.michja56.backend.model.Cart;
import com.osu.michja56.backend.model.CartItem;
import com.osu.michja56.backend.model.Product;
import com.osu.michja56.backend.model.User;
import com.osu.michja56.backend.repository.CartItemRepository;
import com.osu.michja56.backend.repository.CartRepository;
import com.osu.michja56.backend.repository.ProductRepository;
import com.osu.michja56.backend.repository.UserRepository;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

@SpringBootTest
@Transactional
class OrderServiceTest {

    @Autowired
    private OrderService orderService;

    @Autowired
    private UserRepository userRepository;

    @Autowired
    private ProductRepository productRepository;

    @Autowired
    private CartRepository cartRepository;

    @Autowired
    private CartItemRepository cartItemRepository;

    @Test
    void createsOrderFromCartAndClearsCart() {
        User user = new User();
        user.setUsername("order_test_user");
        user.setPassword("test");
        user.setEmail("order_test_user@example.com");
        user.setFirstName("Test");
        user.setLastName("User");
        user.setStreet("Testovací 1");
        user.setCity("Olomouc");
        user.setPostalCode("77900");
        user.setPhone("+420777000333");
        user.setRole("USER");
        user = userRepository.save(user);

        Product product = new Product();
        product.setName("Test produkt");
        product.setPrice(new BigDecimal("199.00"));
        product.setStockQuantity(5);
        product = productRepository.save(product);

        Cart cart = new Cart();
        cart.setUser(user);
        cart = cartRepository.save(cart);

        CartItem item = new CartItem();
        item.setCart(cart);
        item.setProduct(product);
        item.setQuantity(2);
        item.setPriceAtAdd(product.getPrice());
        cartItemRepository.save(item);

        OrderCreateRequest request = new OrderCreateRequest();
        request.setUseProfile(true);
        request.setShippingMethod("ZASILKOVNA");

        var orderResponse = orderService.createOrderFromCart(user.getId(), request);

        assertEquals(new BigDecimal("398.00"), orderResponse.getTotal());
        assertEquals(1, orderResponse.getItems().size());
        assertTrue(cartItemRepository.findByCartId(cart.getId()).isEmpty());

        Product updated = productRepository.findById(product.getId()).orElseThrow();
        assertEquals(3, updated.getStockQuantity());
    }
}

import React, { useEffect, useState } from 'react';
import 'bootstrap/dist/css/bootstrap.min.css';
import ProductList from './components/ProductList';
import Login from './components/Login'; // Import nového Loginu
import Cart from './components/Cart';
import ChangePassword from './components/ChangePassword';
import AdminProducts from './components/AdminProducts';
import AdminOrders from './components/AdminOrders';
import UserOrders from './components/UserOrders';
import BillingProfile from './components/BillingProfile';
import Checkout from './components/Checkout';

function App() {
    const [user, setUser] = useState(null);
    const [showLogin, setShowLogin] = useState(false);
    const [cartRefreshKey, setCartRefreshKey] = useState(0);
    const [showUserMenu, setShowUserMenu] = useState(false);
    const [activePage, setActivePage] = useState('products');

    const isAdmin = user?.role === 'ADMIN';
    const isUser = user?.role === 'USER';
    const isGuest = !user;

    useEffect(() => {
        let pageName = 'Produkty';
        if (showLogin && !user) {
            pageName = 'Přihlášení';
        } else if (activePage === 'cart') {
            pageName = 'Košík';
        } else if (activePage === 'checkout') {
            pageName = 'Objednávka';
        } else if (activePage === 'change-password') {
            pageName = 'Změna hesla';
        } else if (activePage === 'profile') {
            pageName = 'Fakturační údaje';
        } else if (activePage === 'admin-products') {
            pageName = 'Sklad';
        } else if (activePage === 'admin-orders') {
            pageName = 'Objednávky';
        } else if (activePage === 'user-orders') {
            pageName = 'Moje objednávky';
        }
        document.title = `IT-shop | ${pageName}`;
    }, [showLogin, activePage, user]);

    const handleLoginSuccess = (userData) => {
        setUser(userData);
        setShowLogin(false);
        if (userData?.role === 'ADMIN') {
            setActivePage('admin-products');
        } else {
            setActivePage('products');
        }
    };

    const handleProfileUpdated = (updatedUser) => {
        setUser(updatedUser);
    };

    return (
        <div className="min-vh-100 bg-light pb-5">
            <nav className="navbar navbar-dark bg-dark mb-4 shadow">
                <div className="container">
                    <span className="navbar-brand mb-0 h1">IT-shop</span>
                    <div>
                        {user ? (
                            <div className="d-flex align-items-center gap-2">
                                {isAdmin ? (
                                    <>
                                        <button
                                            className={`btn btn-outline-light btn-sm ${activePage === 'admin-products' ? 'active' : ''}`}
                                            onClick={() => setActivePage('admin-products')}
                                        >
                                            Sklad
                                        </button>
                                        <button
                                            className={`btn btn-outline-light btn-sm ${activePage === 'admin-orders' ? 'active' : ''}`}
                                            onClick={() => setActivePage('admin-orders')}
                                        >
                                            Objednávky
                                        </button>
                                    </>
                                ) : (
                                    <>
                                        <button
                                            className={`btn btn-outline-light btn-sm ${activePage === 'products' ? 'active' : ''}`}
                                            onClick={() => setActivePage('products')}
                                        >
                                            Produkty
                                        </button>
                                        <button
                                            className={`btn btn-outline-light btn-sm ${activePage === 'user-orders' ? 'active' : ''}`}
                                            onClick={() => setActivePage('user-orders')}
                                        >
                                            Objednávky
                                        </button>
                                        <button
                                            className={`btn btn-outline-light btn-sm ${activePage === 'cart' ? 'active' : ''}`}
                                            onClick={() => setActivePage('cart')}
                                        >
                                            Košík
                                        </button>
                                    </>
                                )}
                                <div className="position-relative">
                                    <button
                                        className="btn btn-outline-light btn-sm"
                                        type="button"
                                        onClick={() => setShowUserMenu((current) => !current)}
                                    >
                                        {user.username}
                                    </button>
                                    {showUserMenu && (
                                        <div className="dropdown-menu dropdown-menu-end show" style={{ position: 'absolute', right: 0 }}>
                                            <button
                                                className="dropdown-item"
                                                type="button"
                                                onClick={() => {
                                                    setActivePage('profile');
                                                    setShowUserMenu(false);
                                                }}
                                            >
                                                Fakturační údaje
                                            </button>
                                            <button
                                                className="dropdown-item"
                                                type="button"
                                                onClick={() => {
                                                    setActivePage('change-password');
                                                    setShowUserMenu(false);
                                                }}
                                            >
                                                Změna hesla
                                            </button>
                                            {isAdmin && (
                                                <button
                                                    className="dropdown-item"
                                                    type="button"
                                                    onClick={() => setActivePage('admin-products')}
                                                >
                                                    Sklad
                                                </button>
                                            )}
                                            <div className="dropdown-divider"></div>
                                            <button
                                                className="dropdown-item text-danger"
                                                type="button"
                                                onClick={() => {
                                                    setUser(null);
                                                    setActivePage('products');
                                                    setShowUserMenu(false);
                                                }}
                                            >
                                                Odhlásit
                                            </button>
                                        </div>
                                    )}
                                </div>
                            </div>
                        ) : (
                            <button className="btn btn-primary btn-sm" onClick={() => setShowLogin(!showLogin)}>
                                {showLogin ? "Zpět na produkty" : "Přihlásit se"}
                            </button>
                        )}
                    </div>
                </div>
            </nav>

            <div className="container">
                {showLogin && !user ? (
                    <Login onLoginSuccess={handleLoginSuccess} />
                ) : (
                    <div>
                        {isUser && activePage === 'cart' && (
                            <Cart
                                user={user}
                                refreshKey={cartRefreshKey}
                                onCartChanged={() => setCartRefreshKey(k => k + 1)}
                                onCheckout={() => setActivePage('checkout')}
                            />
                        )}
                        {isUser && activePage === 'checkout' && (
                            <Checkout
                                user={user}
                                onOrderPlaced={() => setActivePage('user-orders')}
                            />
                        )}
                        {user && activePage === 'change-password' && (
                            <ChangePassword user={user} />
                        )}
                        {user && activePage === 'profile' && (
                            <BillingProfile user={user} onProfileUpdated={handleProfileUpdated} />
                        )}
                        {isAdmin && activePage === 'admin-products' && (
                            <AdminProducts />
                        )}
                        {isAdmin && activePage === 'admin-orders' && (
                            <AdminOrders user={user} />
                        )}
                        {isUser && activePage === 'user-orders' && (
                            <UserOrders user={user} />
                        )}
                        {(isGuest || isUser) && activePage === 'products' && (
                            <div>
                                <h2 className="fw-light mb-4">Naše nabídka</h2>
                                <ProductList
                                    key={0}
                                    user={user}
                                    onCartChanged={() => setCartRefreshKey(k => k + 1)}
                                />
                            </div>
                        )}
                    </div>
                )}
            </div>
            <footer className="text-center text-muted py-4 mt-5 border-top">
                <small>© 2026 IT-shop · Vytvořeno v rámci předmětu SWI1</small>
            </footer>
        </div>
    );
}

