import { useEffect, useState } from 'react';
import axios from 'axios';

const STATUSES = [
    { value: 'NEW', label: 'Nová' },
    { value: 'PAID', label: 'Zaplacena' },
    { value: 'SHIPPED', label: 'Odeslána' },
    { value: 'CANCELED', label: 'Zrušena' }
];

const SHIPPING_LABELS = {
    ZASILKOVNA: 'Zásilkovna na výdejní místo',
    BALIKOVNA: 'Balíkovna na výdejní místo',
    PPL: 'PPL na adresu'
};

const AdminOrders = ({ user }) => {
    const [orders, setOrders] = useState([]);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');

    const loadOrders = () => {
        if (!user) return;
        setLoading(true);
        axios.get(`http://localhost:8080/api/orders/admin/${user.id}`)
            .then(response => {
                setOrders(response.data);
                setError('');
            })
            .catch(err => {
                setError(err.response?.data || 'Objednávky se nepodařilo načíst.');
            })
            .finally(() => setLoading(false));
    };

    useEffect(() => {
        loadOrders();
    }, [user]);

    const handleStatusChange = (orderId, status) => {
        axios.patch(`http://localhost:8080/api/orders/admin/${user.id}/${orderId}/status`, { status })
            .then(() => loadOrders())
            .catch(err => {
                setError(err.response?.data || 'Změna stavu selhala.');
            });
    };

    if (!user) return null;

    return (
        <div className="card shadow-sm">
            <div className="card-body">
                <h3 className="card-title h5 mb-3">Objednávky</h3>
                {loading && <div>Načítám...</div>}
                {error && <div className="alert alert-danger">{error}</div>}
                {!loading && !error && orders.length === 0 && (
                    <div className="text-muted">Zatím nejsou žádné objednávky.</div>
                )}
                {!loading && !error && orders.length > 0 && (
                    <div className="d-grid gap-3">
                        {orders.map(order => (
                            <div key={order.id} className="border rounded p-3">
                                <div className="d-flex flex-wrap justify-content-between align-items-center mb-2">
                                    <div>
                                        <strong>Objednávka #{order.id}</strong>
                                        <div className="text-muted small">Uživatel ID: {order.userId}</div>
                                    </div>
                                    <div className="d-flex align-items-center gap-2">
                                        <select
                                            className="form-select form-select-sm"
                                            value={order.status}
                                            onChange={e => handleStatusChange(order.id, e.target.value)}
                                        >
                                            {STATUSES.map(status => (
                                                <option key={status.value} value={status.value}>{status.label}</option>
                                            ))}
                                        </select>
                                        <span className="fw-semibold">
                                            {Number(order.total).toLocaleString('cs-CZ')} Kč
                                        </span>
                                    </div>
                                </div>
                                <div className="text-muted small mb-2">
                                    {order.billingFirstName} {order.billingLastName} · {order.billingEmail} · {order.billingPhone}
                                </div>
                                <div className="text-muted small mb-2">
                                    {order.billingStreet}, {order.billingCity} {order.billingPostalCode}
                                </div>
                                <div className="text-muted small mb-3">
                                    Doprava: {SHIPPING_LABELS[order.shippingMethod] || order.shippingMethod}
                                </div>
                                <div className="table-responsive">
                                    <table className="table table-sm mb-0">
                                        <thead>
                                        <tr>
                                            <th>Produkt</th>
                                            <th className="text-end">Množství</th>
                                            <th className="text-end">Cena</th>
                                            <th className="text-end">Celkem</th>
                                        </tr>
                                        </thead>
                                        <tbody>
                                        {order.items.map(item => (
                                            <tr key={item.id}>
                                                <td>{item.productName}</td>
                                                <td className="text-end">{item.quantity}</td>
                                                <td className="text-end">{Number(item.priceAtOrder).toLocaleString('cs-CZ')} Kč</td>
                                                <td className="text-end">{Number(item.lineTotal).toLocaleString('cs-CZ')} Kč</td>
                                            </tr>
                                        ))}
                                        </tbody>
                                    </table>
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </div>
        </div>
    );
};

export default AdminOrders;

import { useEffect, useState } from 'react';
import axios from 'axios';
import AddProductForm from './AddProductForm';

const AdminProducts = () => {
    const [products, setProducts] = useState([]);
    const [loading, setLoading] = useState(true);
    const [stockEdits, setStockEdits] = useState({});

    const loadProducts = () => {
        axios.get('http://localhost:8080/api/products')
            .then(response => {
                setProducts(response.data);
                setLoading(false);
            })
            .catch(error => {
                console.error('Chyba při komunikaci s backendem:', error);
                setLoading(false);
            });
    };

    useEffect(() => {
        loadProducts();
    }, []);

    const handleDelete = (id) => {
        if (!window.confirm('Opravdu chcete smazat tento produkt?')) return;
        axios.delete(`http://localhost:8080/api/products/${id}`)
            .then(() => loadProducts())
            .catch(error => console.error('Chyba při mazání:', error));
    };

    const handleStockChange = (id, value) => {
        setStockEdits(prev => ({ ...prev, [id]: value }));
    };

    const handleStockSave = (id) => {
        const stockQuantity = Number(stockEdits[id]);
        if (!Number.isInteger(stockQuantity) || stockQuantity < 0) {
            alert('Zadejte nezáporné celé číslo.');
            return;
        }
        axios.patch(`http://localhost:8080/api/products/${id}/stock`, { stockQuantity })
            .then(() => loadProducts())
            .catch(error => console.error('Chyba při ukládání skladu:', error));
    };

    return (
        <div>
            <AddProductForm onProductAdded={loadProducts} />
            <div className="card shadow-sm">
                <div className="card-body">
                    <h3 className="card-title h5 mb-3">Sklad produktů</h3>
                    {loading && <div>Načítám...</div>}
                    {!loading && products.length === 0 && (
                        <div className="text-muted">Zatím zde nejsou žádné produkty.</div>
                    )}
                    {!loading && products.length > 0 && (
                        <div className="table-responsive">
                            <table className="table table-sm align-middle">
                                <thead>
                                <tr>
                                    <th>Název</th>
                                    <th className="text-end">Cena</th>
                                    <th className="text-end">Skladem</th>
                                    <th className="text-end">Akce</th>
                                </tr>
                                </thead>
                                <tbody>
                                {products.map(product => (
                                    <tr key={product.id}>
                                        <td>{product.name}</td>
                                        <td className="text-end">
                                            {Number(product.price).toLocaleString('cs-CZ')} Kč
                                        </td>
                                        <td className="text-end" style={{ maxWidth: '120px' }}>
                                            <input
                                                type="number"
                                                className="form-control form-control-sm"
                                                min="0"
                                                value={stockEdits[product.id] ?? product.stockQuantity ?? 0}
                                                onChange={e => handleStockChange(product.id, e.target.value)}
                                            />
                                        </td>
                                        <td className="text-end">
                                            <div className="btn-group btn-group-sm">
                                                <button
                                                    className="btn btn-outline-success"
                                                    type="button"
                                                    onClick={() => handleStockSave(product.id)}
                                                >
                                                    Uložit sklad
                                                </button>
                                                <button
                                                    className="btn btn-outline-danger"
                                                    type="button"
                                                    onClick={() => handleDelete(product.id)}
                                                >
                                                    Smazat
                                                </button>
                                            </div>
                                        </td>
                                    </tr>
                                ))}
                                </tbody>
                            </table>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default AdminProducts;

import { useEffect, useState } from 'react';
import axios from 'axios';

const BillingProfile = ({ user, onProfileUpdated }) => {
    const [form, setForm] = useState({
        firstName: '',
        lastName: '',
        street: '',
        city: '',
        postalCode: '',
        email: '',
        phone: ''
    });
    const [message, setMessage] = useState('');
    const [error, setError] = useState('');

    useEffect(() => {
        if (!user) return;
        setForm({
            firstName: user.firstName || '',
            lastName: user.lastName || '',
            street: user.street || '',
            city: user.city || '',
            postalCode: user.postalCode || '',
            email: user.email || '',
            phone: user.phone || ''
        });
    }, [user]);

    const handleSubmit = (e) => {
        e.preventDefault();
        setMessage('');
        setError('');

        axios.put(`http://localhost:8080/api/users/${user.id}/profile`, form)
            .then(response => {
                setMessage('Fakturační údaje byly uloženy.');
                onProfileUpdated?.(response.data);
            })
            .catch(err => {
                setError(err.response?.data || 'Uložení selhalo.');
            });
    };

    if (!user) return null;

    return (
        <div className="card shadow-sm mb-4">
            <div className="card-body">
                <h3 className="card-title h5 mb-3">Fakturační údaje</h3>
                {error && <div className="alert alert-danger">{error}</div>}
                {message && <div className="alert alert-success">{message}</div>}
                <form onSubmit={handleSubmit}>
                    <div className="mb-3">
                        <label className="form-label">Jméno</label>
                        <input
                            type="text"
                            className="form-control"
                            required
                            value={form.firstName}
                            onChange={e => setForm({ ...form, firstName: e.target.value })}
                        />
                    </div>
                    <div className="mb-3">
                        <label className="form-label">Příjmení</label>
                        <input
                            type="text"
                            className="form-control"
                            required
                            value={form.lastName}
                            onChange={e => setForm({ ...form, lastName: e.target.value })}
                        />
                    </div>
                    <div className="mb-3">
                        <label className="form-label">Ulice</label>
                        <input
                            type="text"
                            className="form-control"
                            required
                            value={form.street}
                            onChange={e => setForm({ ...form, street: e.target.value })}
                        />
                    </div>
                    <div className="mb-3">
                        <label className="form-label">Město</label>
                        <input
                            type="text"
                            className="form-control"
                            required
                            value={form.city}
                            onChange={e => setForm({ ...form, city: e.target.value })}
                        />
                    </div>
                    <div className="mb-3">
                        <label className="form-label">PSČ</label>
                        <input
                            type="text"
                            className="form-control"
                            required
                            value={form.postalCode}
                            onChange={e => setForm({ ...form, postalCode: e.target.value })}
                        />
                    </div>
                    <div className="mb-3">
                        <label className="form-label">E-mail</label>
                        <input
                            type="email"
                            className="form-control"
                            required
                            value={form.email}
                            onChange={e => setForm({ ...form, email: e.target.value })}
                        />
                    </div>
                    <div className="mb-3">
                        <label className="form-label">Telefon</label>
                        <input
                            type="tel"
                            className="form-control"
                            required
                            value={form.phone}
                            onChange={e => setForm({ ...form, phone: e.target.value })}
                        />
                    </div>
                    <button type="submit" className="btn btn-outline-primary w-100">
                        Uložit údaje
                    </button>
                </form>
            </div>
        </div>
    );
};

export default BillingProfile;

import React, { useEffect, useState } from 'react';
import axios from 'axios';

const Cart = ({ user, refreshKey, onCartChanged, onCheckout }) => {
    const [cart, setCart] = useState(null);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');
    const [quantityEdits, setQuantityEdits] = useState({});

    const loadCart = () => {
        if (!user) return;
        setLoading(true);
        axios.get(`http://localhost:8080/api/cart/${user.id}`)
            .then(response => {
                setCart(response.data);
                setQuantityEdits({});
                setError('');
            })
            .catch(err => {
                setError(err.response?.data || 'Košík se nepodařilo načíst.');
            })
            .finally(() => setLoading(false));
    };

    useEffect(() => {
        loadCart();
    }, [user, refreshKey]);

    const handleQuantityChange = (itemId, value) => {
        setQuantityEdits(prev => ({ ...prev, [itemId]: value }));
    };

    const handleQuantitySave = (itemId) => {
        const quantity = Number(quantityEdits[itemId]);
        if (!Number.isInteger(quantity) || quantity < 0) {
            alert('Zadejte nezáporné celé číslo.');
            return;
        }

        axios.patch(`http://localhost:8080/api/cart/${user.id}/items/${itemId}`, { quantity })
            .then(() => {
                onCartChanged?.();
            })
            .catch(err => {
                alert(err.response?.data || 'Uložení množství selhalo.');
            });
    };

    const handleRemove = (itemId) => {
        axios.delete(`http://localhost:8080/api/cart/${user.id}/items/${itemId}`)
            .then(() => {
                onCartChanged?.();
            })
            .catch(err => {
                alert(err.response?.data || 'Odebrání položky selhalo.');
            });
    };

    if (!user) return null;

    return (
        <div className="card shadow-sm mb-4">
            <div className="card-body">
                <h3 className="card-title h5 mb-3">Košík</h3>
                {loading && <div>Načítám...</div>}
                {error && <div className="alert alert-danger">{error}</div>}
                {!loading && !error && (!cart || cart.items.length === 0) && (
                    <div className="text-muted">Košík je prázdný.</div>
                )}
                {!loading && !error && cart && cart.items.length > 0 && (
                    <div>
                        {cart.items.map(item => (
                            <div key={item.id} className="border-bottom pb-2 mb-2">
                                <div className="fw-semibold">{item.productName}</div>
                                <div className="text-muted small">
                                    {Number(item.price).toLocaleString('cs-CZ')} Kč / ks
                                </div>
                                <div className="input-group input-group-sm mt-2">
                                    <input
                                        type="number"
                                        className="form-control"
                                        min="0"
                                        value={quantityEdits[item.id] ?? item.quantity}
                                        onChange={e => handleQuantityChange(item.id, e.target.value)}
                                    />
                                    <button
                                        className="btn btn-outline-success"
                                        type="button"
                                        onClick={() => handleQuantitySave(item.id)}
                                    >
                                        Uložit
                                    </button>
                                    <button
                                        className="btn btn-outline-danger"
                                        type="button"
                                        onClick={() => handleRemove(item.id)}
                                    >
                                        Odebrat
                                    </button>
                                </div>
                                <div className="text-end text-muted small mt-1">
                                    {Number(item.lineTotal).toLocaleString('cs-CZ')} Kč
                                </div>
                            </div>
                        ))}
                        <div className="d-flex justify-content-between fw-semibold mt-3">
                            <span>Celková cena</span>
                            <span>{Number(cart.total).toLocaleString('cs-CZ')} Kč</span>
                        </div>
                        {user?.role === 'USER' && (
                            <div className="mt-3">
                                <button
                                    className="btn btn-primary w-100"
                                    type="button"
                                    onClick={onCheckout}
                                >
                                    Pokračovat k objednávce
                                </button>
                            </div>
                        )}
                    </div>
                )}
            </div>
        </div>
    );
};

export default Cart;

import React, { useState } from 'react';
import axios from 'axios';

const ChangePassword = ({ user }) => {
    const [currentPassword, setCurrentPassword] = useState('');
    const [newPassword, setNewPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [message, setMessage] = useState('');
    const [error, setError] = useState('');

    const handleSubmit = (e) => {
        e.preventDefault();
        setMessage('');
        setError('');

        if (newPassword !== confirmPassword) {
            setError('Nové heslo a potvrzení se neshodují.');
            return;
        }

        axios.post('http://localhost:8080/api/auth/change-password', {
            userId: user.id,
            currentPassword,
            newPassword
        })
            .then(() => {
                setMessage('Heslo bylo změněno.');
                setCurrentPassword('');
                setNewPassword('');
                setConfirmPassword('');
            })
            .catch(err => {
                setError(err.response?.data || 'Změna hesla selhala.');
            });
    };

    if (!user) return null;

    return (
        <div className="card shadow-sm mb-4">
            <div className="card-body">
                <h3 className="card-title h5 mb-3">Změna hesla</h3>
                {error && <div className="alert alert-danger">{error}</div>}
                {message && <div className="alert alert-success">{message}</div>}
                <form onSubmit={handleSubmit}>
                    <div className="mb-3">
                        <label className="form-label">Aktuální heslo</label>
                        <input
                            type="password"
                            className="form-control"
                            required
                            value={currentPassword}
                            onChange={e => setCurrentPassword(e.target.value)}
                        />
                    </div>
                    <div className="mb-3">
                        <label className="form-label">Nové heslo</label>
                        <input
                            type="password"
                            className="form-control"
                            required
                            value={newPassword}
                            onChange={e => setNewPassword(e.target.value)}
                        />
                    </div>
                    <div className="mb-3">
                        <label className="form-label">Potvrzení nového hesla</label>
                        <input
                            type="password"
                            className="form-control"
                            required
                            value={confirmPassword}
                            onChange={e => setConfirmPassword(e.target.value)}
                        />
                    </div>
                    <button type="submit" className="btn btn-outline-primary w-100">
                        Změnit heslo
                    </button>
                </form>
            </div>
        </div>
    );
};

export default ChangePassword;

import { useEffect, useMemo, useState } from 'react';
import axios from 'axios';

const SHIPPING_OPTIONS = [
    { id: 'zasilkovna', label: 'Zásilkovna na výdejní místo', pickup: true },
    { id: 'balikovna', label: 'Balíkovna na výdejní místo', pickup: true },
    { id: 'ppl', label: 'PPL na adresu', pickup: false }
];

const Checkout = ({ user, onOrderPlaced }) => {
    const [cart, setCart] = useState(null);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');
    const [message, setMessage] = useState('');
    const [useProfile, setUseProfile] = useState(true);
    const [shippingMethod, setShippingMethod] = useState('zasilkovna');
    const [billingForm, setBillingForm] = useState({
        firstName: '',
        lastName: '',
        street: '',
        city: '',
        postalCode: '',
        email: '',
        phone: ''
    });

    useEffect(() => {
        if (!user) return;
        setLoading(true);
        axios.get(`http://localhost:8080/api/cart/${user.id}`)
            .then(response => {
                setCart(response.data);
                setError('');
                setMessage('');
                setBillingForm({
                    firstName: user?.firstName || '',
                    lastName: user?.lastName || '',
                    street: user?.street || '',
                    city: user?.city || '',
                    postalCode: user?.postalCode || '',
                    email: user?.email || '',
                    phone: user?.phone || ''
                });
            })
            .catch(err => {
                setError(err.response?.data || 'Košík se nepodařilo načíst.');
            })
            .finally(() => setLoading(false));
    }, [user]);

    const selectedShipping = useMemo(
        () => SHIPPING_OPTIONS.find(option => option.id === shippingMethod),
        [shippingMethod]
    );

    const handleOrder = () => {
        if (!cart || !cart.items || cart.items.length === 0) {
            setError('Košík je prázdný.');
            return;
        }
        setError('');
        setMessage('');
        const payload = useProfile ? { useProfile: true } : {
            useProfile: false,
            firstName: billingForm.firstName,
            lastName: billingForm.lastName,
            street: billingForm.street,
            city: billingForm.city,
            postalCode: billingForm.postalCode,
            email: billingForm.email,
            phone: billingForm.phone
        };
        payload.shippingMethod = shippingMethod.toUpperCase();
        axios.post(`http://localhost:8080/api/orders/${user.id}/from-cart`, payload)
            .then(() => {
                setMessage('Objednávka byla vytvořena.');
                onOrderPlaced?.();
            })
            .catch(err => {
                setError(err.response?.data || 'Vytvoření objednávky selhalo.');
            });
    };

    if (!user) return null;

    return (
        <div className="card shadow-sm">
            <div className="card-body">
                <h3 className="card-title h5 mb-3">Dokončení objednávky</h3>
                {loading && <div>Načítám...</div>}
                {error && <div className="alert alert-danger">{error}</div>}
                {message && <div className="alert alert-success">{message}</div>}

                {!loading && cart && (
                    <div className="mb-4">
                        <div className="fw-semibold">Souhrn</div>
                        <div className="text-muted small">Položek: {cart.items.length}</div>
                        <div className="fw-semibold">Celkem: {Number(cart.total).toLocaleString('cs-CZ')} Kč</div>
                    </div>
                )}

                <div className="border rounded p-3 mb-4">
                    <div className="d-flex justify-content-between align-items-center mb-2">
                        <div className="fw-semibold">Fakturační údaje</div>
                        <div className="form-check">
                            <input
                                className="form-check-input"
                                type="checkbox"
                                id="useProfileBilling"
                                checked={useProfile}
                                onChange={e => setUseProfile(e.target.checked)}
                            />
                            <label className="form-check-label" htmlFor="useProfileBilling">
                                Použít uložené
                            </label>
                        </div>
                    </div>
                    {useProfile ? (
                        <div className="text-muted small">
                            <div>{billingForm.firstName} {billingForm.lastName}</div>
                            <div>{billingForm.street}, {billingForm.city} {billingForm.postalCode}</div>
                            <div>{billingForm.email}</div>
                            <div>{billingForm.phone}</div>
                        </div>
                    ) : (
                        <div>
                            <div className="mb-2">
                                <label className="form-label">Jméno</label>
                                <input
                                    type="text"
                                    className="form-control"
                                    value={billingForm.firstName}
                                    onChange={e => setBillingForm({ ...billingForm, firstName: e.target.value })}
                                />
                            </div>
                            <div className="mb-2">
                                <label className="form-label">Příjmení</label>
                                <input
                                    type="text"
                                    className="form-control"
                                    value={billingForm.lastName}
                                    onChange={e => setBillingForm({ ...billingForm, lastName: e.target.value })}
                                />
                            </div>
                            <div className="mb-2">
                                <label className="form-label">Ulice</label>
                                <input
                                    type="text"
                                    className="form-control"
                                    value={billingForm.street}
                                    onChange={e => setBillingForm({ ...billingForm, street: e.target.value })}
                                />
                            </div>
                            <div className="mb-2">
                                <label className="form-label">Město</label>
                                <input
                                    type="text"
                                    className="form-control"
                                    value={billingForm.city}
                                    onChange={e => setBillingForm({ ...billingForm, city: e.target.value })}
                                />
                            </div>
                            <div className="mb-2">
                                <label className="form-label">PSČ</label>
                                <input
                                    type="text"
                                    className="form-control"
                                    value={billingForm.postalCode}
                                    onChange={e => setBillingForm({ ...billingForm, postalCode: e.target.value })}
                                />
                            </div>
                            <div className="mb-2">
                                <label className="form-label">E-mail</label>
                                <input
                                    type="email"
                                    className="form-control"
                                    value={billingForm.email}
                                    onChange={e => setBillingForm({ ...billingForm, email: e.target.value })}
                                />
                            </div>
                            <div>
                                <label className="form-label">Telefon</label>
                                <input
                                    type="tel"
                                    className="form-control"
                                    value={billingForm.phone}
                                    onChange={e => setBillingForm({ ...billingForm, phone: e.target.value })}
                                />
                            </div>
                        </div>
                    )}
                </div>

                <div className="border rounded p-3 mb-4">
                    <div className="fw-semibold mb-2">Doprava</div>
                    {SHIPPING_OPTIONS.map(option => (
                        <div key={option.id} className="form-check mb-2">
                            <input
                                className="form-check-input"
                                type="radio"
                                name="shipping"
                                id={`shipping-${option.id}`}
                                value={option.id}
                                checked={shippingMethod === option.id}
                                onChange={e => setShippingMethod(e.target.value)}
                            />
                            <label className="form-check-label" htmlFor={`shipping-${option.id}`}>
                                {option.label}
                            </label>
                        </div>
                    ))}
                    {selectedShipping?.pickup && (
                        <button type="button" className="btn btn-outline-secondary btn-sm">
                            Vybrat výdejní místo
                        </button>
                    )}
                </div>

                <button className="btn btn-success w-100" type="button" onClick={handleOrder}>
                    Odeslat objednávku
                </button>
            </div>
        </div>
    );
};

export default Checkout;

import React, { useState } from 'react';
import axios from 'axios';

const Login = ({ onLoginSuccess }) => {
    const [mode, setMode] = useState('login');
    const [credentials, setCredentials] = useState({ username: '', password: '' });
    const [registerData, setRegisterData] = useState({
        username: '',
        password: '',
        confirmPassword: '',
        email: '',
        firstName: '',
        lastName: '',
        street: '',
        city: '',
        postalCode: '',
        phone: ''
    });
    const [error, setError] = useState('');
    const [success, setSuccess] = useState('');

    const handleLogin = (e) => {
        e.preventDefault();
        setSuccess('');
        axios.post('http://localhost:8080/api/auth/login', credentials)
            .then(response => {
                onLoginSuccess(response.data); // Předáme data uživatele do App.jsx
                setError('');
            })
            .catch(err => {
                setError('Špatné jméno nebo heslo');
            });
    };

    const handleRegister = (e) => {
        e.preventDefault();
        setError('');
        if (registerData.password !== registerData.confirmPassword) {
            setError('Hesla se neshodují.');
            return;
        }
        const { confirmPassword, ...payload } = registerData;
        axios.post('http://localhost:8080/api/auth/register', payload)
            .then(response => {
                setSuccess('Registrace proběhla úspěšně.');
                onLoginSuccess(response.data);
            })
            .catch(err => {
                const message = err.response?.data || 'Registrace se nezdařila.';
                setError(message);
            });
    };

    return (
        <div className="card shadow-sm mx-auto" style={{maxWidth: '400px'}}>
            <div className="card-body">
                <div className="btn-group w-100 mb-3" role="group">
                    <button
                        type="button"
                        className={`btn ${mode === 'login' ? 'btn-primary' : 'btn-outline-primary'}`}
                        onClick={() => { setMode('login'); setError(''); setSuccess(''); }}
                    >
                        Přihlášení
                    </button>
                    <button
                        type="button"
                        className={`btn ${mode === 'register' ? 'btn-primary' : 'btn-outline-primary'}`}
                        onClick={() => { setMode('register'); setError(''); setSuccess(''); }}
                    >
                        Registrace
                    </button>
                </div>
                <h3 className="card-title text-center mb-4">
                    {mode === 'login' ? 'Přihlášení' : 'Registrace'}
                </h3>
                {error && <div className="alert alert-danger">{error}</div>}
                {success && <div className="alert alert-success">{success}</div>}

                {mode === 'login' ? (
                    <form onSubmit={handleLogin}>
                        <div className="mb-3">
                            <label className="form-label">Uživatelské jméno</label>
                            <input
                                type="text" className="form-control" required
                                onChange={e => setCredentials({...credentials, username: e.target.value})}
                            />
                        </div>
                        <div className="mb-3">
                            <label className="form-label">Heslo</label>
                            <input
                                type="password" className="form-control" required
                                onChange={e => setCredentials({...credentials, password: e.target.value})}
                            />
                        </div>
                        <button type="submit" className="btn btn-primary w-100">Přihlásit se</button>
                    </form>
                ) : (
                    <form onSubmit={handleRegister}>
                        <div className="mb-3">
                            <label className="form-label">Uživatelské jméno</label>
                            <input
                                type="text" className="form-control" required
                                onChange={e => setRegisterData({...registerData, username: e.target.value})}
                            />
                        </div>
                        <div className="mb-3">
                            <label className="form-label">E-mail</label>
                            <input
                                type="email" className="form-control" required
                                onChange={e => setRegisterData({...registerData, email: e.target.value})}
                            />
                        </div>
                        <div className="mb-3">
                            <label className="form-label">Jméno</label>
                            <input
                                type="text" className="form-control" required
                                onChange={e => setRegisterData({...registerData, firstName: e.target.value})}
                            />
                        </div>
                        <div className="mb-3">
                            <label className="form-label">Příjmení</label>
                            <input
                                type="text" className="form-control" required
                                onChange={e => setRegisterData({...registerData, lastName: e.target.value})}
                            />
                        </div>
                        <div className="mb-3">
                            <label className="form-label">Ulice</label>
                            <input
                                type="text" className="form-control" required
                                onChange={e => setRegisterData({...registerData, street: e.target.value})}
                            />
                        </div>
                        <div className="mb-3">
                            <label className="form-label">Město</label>
                            <input
                                type="text" className="form-control" required
                                onChange={e => setRegisterData({...registerData, city: e.target.value})}
                            />
                        </div>
                        <div className="mb-3">
                            <label className="form-label">PSČ</label>
                            <input
                                type="text" className="form-control" required
                                onChange={e => setRegisterData({...registerData, postalCode: e.target.value})}
                            />
                        </div>
                        <div className="mb-3">
                            <label className="form-label">Telefon</label>
                            <input
                                type="tel" className="form-control" required
                                onChange={e => setRegisterData({...registerData, phone: e.target.value})}
                            />
                        </div>
                        <div className="mb-3">
                            <label className="form-label">Heslo</label>
                            <input
                                type="password" className="form-control" required
                                onChange={e => setRegisterData({...registerData, password: e.target.value})}
                            />
                        </div>
                        <div className="mb-3">
                            <label className="form-label">Potvrzení hesla</label>
                            <input
                                type="password" className="form-control" required
                                onChange={e => setRegisterData({...registerData, confirmPassword: e.target.value})}
                            />
                        </div>
                        <button type="submit" className="btn btn-primary w-100">Zaregistrovat se</button>
                    </form>
                )}
            </div>
        </div>
    );
};

export default Login;

import React, { useState, useEffect } from 'react';
import axios from 'axios';

const ProductList = ({ user }) => {
    const [products, setProducts] = useState([]);
    const [loading, setLoading] = useState(true);

    const loadProducts = () => {
        axios.get('http://localhost:8080/api/products')
            .then(response => {
                setProducts(response.data);
                setLoading(false);
            })
            .catch(error => {
                console.error('Chyba při komunikaci s backendem:', error);
                setLoading(false);
            });
    };

    useEffect(() => {
        loadProducts();
    }, []);

    const handleDelete = (id) => {
        if (!window.confirm('Opravdu chcete smazat tento produkt?')) return;
        axios.delete(`http://localhost:8080/api/products/${id}`)
            .then(() => loadProducts())
            .catch(error => console.error('Chyba při mazání:', error));
    };

    if (loading) return <div className="text-center">Načítám produkty...</div>;

    return (
        <div className="row">
            {products.map(product => (
                <div key={product.id} className="col-md-4 mb-4">
                    <div className="card h-100 shadow-sm">
                        <img
                            src={product.imageUrl || "https://placehold.co/400x400?text=Bez+obrazku"}
                            className="card-img-top"
                            alt={product.name}
                        />
                        <div className="card-body">
                            <h5 className="card-title fw-bold">{product.name}</h5>
                            <p className="card-text text-muted small">{product.description}</p>
                            <div className="d-flex justify-content-between align-items-center mt-3">
                                <span className="h5 mb-0 text-success">
                                    {Number(product.price).toLocaleString('cs-CZ')} Kč
                                </span>
                                <button className="btn btn-outline-primary btn-sm">Detail</button>
                            </div>
                            {user?.role === 'ADMIN' && (
                                <button
                                    className="btn btn-danger btn-sm w-100 mt-2"
                                    onClick={() => handleDelete(product.id)}
                                >
                                     Smazat produkt
                                </button>
                            )}
                        </div>
                    </div>
                </div>
            ))}
        </div>
    );
};

export default ProductList;

import React, { useState, useEffect } from 'react';
import axios from 'axios';

const ProductList = ({ user, onCartChanged }) => {
    const [products, setProducts] = useState([]);
    const [loading, setLoading] = useState(true);
    const [stockEdits, setStockEdits] = useState({});

    const loadProducts = () => {
        axios.get('http://localhost:8080/api/products')
            .then(response => {
                setProducts(response.data);
                setLoading(false);
            })
            .catch(error => {
                console.error('Chyba při komunikaci s backendem:', error);
                setLoading(false);
            });
    };

    useEffect(() => {
        loadProducts();
    }, []);

    const handleDelete = (id) => {
        if (!window.confirm('Opravdu chcete smazat tento produkt?')) return;
        axios.delete(`http://localhost:8080/api/products/${id}`)
            .then(() => loadProducts())
            .catch(error => console.error('Chyba při mazání:', error));
    };

    const handleAddToCart = (productId) => {
        if (!user) return;
        axios.post(`http://localhost:8080/api/cart/${user.id}/items`, {
            productId,
            quantity: 1
        })
            .then(() => onCartChanged?.())
            .catch(error => alert(error.response?.data || 'Přidání do košíku selhalo.'));
    };

    const handleStockChange = (id, value) => {
        setStockEdits(prev => ({ ...prev, [id]: value }));
    };

    const handleStockSave = (id) => {
        const stockQuantity = Number(stockEdits[id]);
        if (!Number.isInteger(stockQuantity) || stockQuantity < 0) {
            alert('Zadejte nezáporné celé číslo.');
            return;
        }
        axios.patch(`http://localhost:8080/api/products/${id}/stock`, { stockQuantity })
            .then(() => loadProducts())
            .catch(error => console.error('Chyba při ukládání skladu:', error));
    };

    if (loading) return <div className="text-center">Načítám produkty...</div>;

    return (
        <div className="row">
            {products.map(product => (
                <div key={product.id} className="col-md-4 mb-4">
                    <div className="card h-100 shadow-sm">
                        <img
                            src={product.imageUrl || "https://placehold.co/400x400?text=Bez+obrazku"}
                            className="card-img-top"
                            alt={product.name}
                        />
                        <div className="card-body">
                            <h5 className="card-title fw-bold">{product.name}</h5>
                            <p className="card-text text-muted small">{product.description}</p>
                            <div className="d-flex justify-content-between align-items-center mt-3">
                                <span className="h5 mb-0 text-success">
                                    {Number(product.price).toLocaleString('cs-CZ')} Kč
                                </span>
                                <button className="btn btn-outline-primary btn-sm">Detail</button>
                            </div>
                            <div className="text-muted small mt-2">
                                Skladem: {product.stockQuantity ?? 0} ks
                            </div>
                            {user && (
                                <button
                                    className="btn btn-primary btn-sm w-100 mt-2"
                                    onClick={() => handleAddToCart(product.id)}
                                    disabled={(product.stockQuantity ?? 0) <= 0}
                                >
                                    Přidat do košíku
                                </button>
                            )}
                            {user?.role === 'ADMIN' && (
                                <div className="mt-2">
                                    <div className="input-group input-group-sm">
                                        <input
                                            type="number"
                                            className="form-control"
                                            min="0"
                                            value={stockEdits[product.id] ?? product.stockQuantity ?? 0}
                                            onChange={e => handleStockChange(product.id, e.target.value)}
                                        />
                                        <button
                                            className="btn btn-outline-success"
                                            type="button"
                                            onClick={() => handleStockSave(product.id)}
                                        >
                                            Uložit sklad
                                        </button>
                                    </div>
                                </div>
                            )}
                            {user?.role === 'ADMIN' && (
                                <button
                                    className="btn btn-danger btn-sm w-100 mt-2"
                                    onClick={() => handleDelete(product.id)}
                                >
                                     Smazat produkt
                                </button>
                            )}
                        </div>
                    </div>
                </div>
            ))}
        </div>
    );
};

export default ProductList;

import { useEffect, useState } from 'react';
import axios from 'axios';

const STATUS_LABELS = {
    NEW: 'Nová',
    PAID: 'Zaplacená',
    SHIPPED: 'Odeslaná',
    CANCELED: 'Zrušená'
};

const STATUS_BADGE_CLASSES = {
    NEW: 'bg-secondary',
    PAID: 'bg-success',
    SHIPPED: 'bg-primary',
    CANCELED: 'bg-danger'
};

const SHIPPING_LABELS = {
    ZASILKOVNA: 'Zásilkovna na výdejní místo',
    BALIKOVNA: 'Balíkovna na výdejní místo',
    PPL: 'PPL na adresu'
};

const UserOrders = ({ user }) => {
    const [orders, setOrders] = useState([]);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');

    const loadOrders = () => {
        if (!user) return;
        setLoading(true);
        axios.get(`http://localhost:8080/api/orders/${user.id}`)
            .then(response => {
                setOrders(response.data);
                setError('');
            })
            .catch(err => {
                setError(err.response?.data || 'Objednávky se nepodařilo načíst.');
            })
            .finally(() => setLoading(false));
    };

    useEffect(() => {
        loadOrders();
    }, [user]);

    if (!user) return null;

    return (
        <div className="card shadow-sm">
            <div className="card-body">
                <h3 className="card-title h5 mb-3">Moje objednávky</h3>
                {loading && <div>Načítám...</div>}
                {error && <div className="alert alert-danger">{error}</div>}
                {!loading && !error && orders.length === 0 && (
                    <div className="text-muted">Zatím nemáte žádné objednávky.</div>
                )}
                {!loading && !error && orders.length > 0 && (
                    <div className="d-grid gap-3">
                        {orders.map(order => (
                            <div key={order.id} className="border rounded p-3">
                                <div className="d-flex flex-wrap justify-content-between align-items-center mb-2">
                                    <div>
                                        <strong>Objednávka #{order.id}</strong>
                                        <div className="text-muted small">
                                            {order.createdAt ? new Date(order.createdAt).toLocaleString('cs-CZ') : ''}
                                        </div>
                                    </div>
                                    <div className="text-end">
                                        <div className={`badge ${STATUS_BADGE_CLASSES[order.status] || 'bg-secondary'}`}>
                                            {STATUS_LABELS[order.status] || order.status}
                                        </div>
                                        <div className="fw-semibold mt-1">
                                            {Number(order.total).toLocaleString('cs-CZ')} Kč
                                        </div>
                                    </div>
                                </div>
                                <div className="text-muted small mb-2">
                                    {order.billingFirstName} {order.billingLastName} · {order.billingEmail} · {order.billingPhone}
                                </div>
                                <div className="text-muted small mb-2">
                                    {order.billingStreet}, {order.billingCity} {order.billingPostalCode}
                                </div>
                                <div className="text-muted small mb-3">
                                    Doprava: {SHIPPING_LABELS[order.shippingMethod] || order.shippingMethod}
                                </div>
                                <div className="table-responsive">
                                    <table className="table table-sm mb-0">
                                        <thead>
                                        <tr>
                                            <th>Produkt</th>
                                            <th className="text-end">Množství</th>
                                            <th className="text-end">Cena</th>
                                            <th className="text-end">Celkem</th>
                                        </tr>
                                        </thead>
                                        <tbody>
                                        {order.items.map(item => (
                                            <tr key={item.id}>
                                                <td>{item.productName}</td>
                                                <td className="text-end">{item.quantity}</td>
                                                <td className="text-end">{Number(item.priceAtOrder).toLocaleString('cs-CZ')} Kč</td>
                                                <td className="text-end">{Number(item.lineTotal).toLocaleString('cs-CZ')} Kč</td>
                                            </tr>
                                        ))}
                                        </tbody>
                                    </table>
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </div>
        </div>
    );
};

export default UserOrders;
